contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    event RoundCreated(
        address indexed roundAddress,
        address indexed ownedBy,
        address indexed roundImplementation
    );

    function run(
        bytes calldata encodedParameters,
        address ownedBy,
        address newImplementation,
        address newAlloSettings,
        address op
    ) public payable {
        require(newImplementation != address(0), "newImplementation is zero");
        require(newAlloSettings != address(0), "newAlloSettings is zero");

        c.updateRoundImplementation(payable(newImplementation));
        c.updateAlloSettings(newAlloSettings);

        c.updateAlloSettings(address(0));
        require(c.alloSettings() != address(0), "alloSettings unexpectedly zero after update");

        c.updateAlloSettings(newAlloSettings);
        require(c.alloSettings() == newAlloSettings, "alloSettings not restored");

        c.updateProgramOperator(op, true);
        require(c.programOperators(op), "program operator not set");

        address impl = c.roundImplementation();
        address[] memory before = new address[](0);

        bool reverted;
        address created;
        try c.create(encodedParameters, ownedBy) returns (address result) {
            reverted = false;
            created = result;
        } catch {
            reverted = true;
        }

        assert(
            reverted ||
                (created != address(0) && c.roundImplementation() == impl)
        );
    }

    receive() external payable {}
}

