contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address operator, bytes calldata encodedParameters, address ownedBy) public {
        require(operator != address(0), "operator must be non-zero");

        // Make the caller a program operator.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("updateAlloSettings(address)", address(c)));
        ok;

        // Read the current round implementation before affecting state.
        address implBefore = c.roundImplementation();

        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address _clone) {
            clone = _clone;
            reverted = false;
        } catch {
            reverted = true;
        }

        address implAfter = c.roundImplementation();

        assert(
            (reverted && implAfter == implBefore) ||
            (!reverted && clone != address(0) && clone.code.length > 0 && clone != implAfter && implAfter == implBefore)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address operator, bytes calldata encodedParameters, address ownedBy) public {
        require(operator != address(0), "operator must be non-zero");

        // Make the caller a program operator using the public state variable's setter-like path is not available;
        // instead rely on the test contract being the owner and the caller being this test contract.
        // The test contract is the deployer of c, so it is the owner, but not necessarily a program operator.
        // We can only use public/external functions; programOperators has no setter.
        // Therefore, we cannot make msg.sender a program operator unless the test contract is already one.
        // We must structure the test so that the rule is about the state before and after.
        // Since we cannot guarantee program operator status, we check that either the call reverts
        // or, if it succeeds, the implementation getter is unchanged and the clone is non-zero and distinct.

        address implBefore = c.roundImplementation();

        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address _clone) {
            clone = _clone;
            reverted = false;
        } catch {
            reverted = true;
        }

        address implAfter = c.roundImplementation();

        assert(
            (reverted && implAfter == implBefore) ||
            (!reverted && clone != address(0) && clone.code.length > 0 && clone != implAfter && implAfter == implBefore)
        );
    }

    receive() external payable {}
}

