contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newImpl, address newSettings, bool updateImpl) public {
        // Capture whether the caller is the owner before any state-changing attempt.
        address owner = c.owner();
        bool isOwner = (msg.sender == owner);

        // Attempt one of the update calls, as a top-level state-changing statement.
        bool reverted;
        if (updateImpl) {
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // Observe the resulting public state for this branch.
            address observedImpl = c.roundImplementation();
            if (isOwner) {
                assert(!reverted && observedImpl == newImpl);
            } else {
                assert(reverted && observedImpl == address(0));
            }
        } else {
            try c.updateAlloSettings(newSettings) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // Observe the resulting public state for this branch.
            address observedSettings = c.alloSettings();
            if (isOwner) {
                assert(!reverted && observedSettings == newSettings);
            } else {
                assert(reverted && observedSettings == address(0));
            }
        }
    }

    receive() external payable {}
}

